*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #f0f2f5;
  --color-card:        #ffffff;
  --color-primary:     #4f46e5;
  --color-primary-h:   #4338ca;
  --color-primary-f:   #6366f1;
  --color-text:        #111827;
  --color-muted:       #6b7280;
  --color-border:      #d1d5db;
  --color-error:       #dc2626;
  --color-success-bg:  #ecfdf5;
  --color-success:     #15803d;
  --color-focus-ring:  #6366f1;
  --radius:            8px;
  --shadow:            0 4px 24px rgba(0, 0, 0, .08);
}

html { font-size: 100%; }

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: var(--color-bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
               "Helvetica Neue", Arial, sans-serif;
  color: var(--color-text);
  line-height: 1.5;
}

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top .1s;
}
.skip-link:focus { top: 1rem; }

/* ── Card ─────────────────────────────────────────────────── */
.card {
  width: 100%;
  max-width: 480px;
  background: var(--color-card);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: clamp(1.75rem, 6vw, 3rem);
}

/* ── Heading ──────────────────────────────────────────────── */
h1 {
  font-size: clamp(1.375rem, 4vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}

.subtitle {
  margin-top: .5rem;
  color: var(--color-muted);
  font-size: .9375rem;
}

/* ── Form ─────────────────────────────────────────────────── */
form { margin-top: 1.75rem; }

.required-note {
  font-size: .8125rem;
  color: var(--color-muted);
  margin-bottom: 1.25rem;
}

/* ── Form field wrapper ───────────────────────────────────── */
.form-field {
  background: #f8f9fb;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 1rem 1.125rem;
}

/* ── Checkbox row ─────────────────────────────────────────── */
.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: .75rem;
}

/* ── Native checkbox (visually replaced, keyboard-accessible) */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  margin-top: .15rem;          /* optical align with first line of label */
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background: #fff;
  cursor: pointer;
  transition: border-color .15s, background .15s;
  position: relative;
}

input[type="checkbox"]:hover {
  border-color: var(--color-primary);
}

input[type="checkbox"]:checked {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

/* Checkmark via SVG mask */
input[type="checkbox"]:checked::after {
  content: "";
  display: block;
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 12 10' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 5l3.5 3.5L11 1' stroke='%23fff' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E")
    center / 11px 9px no-repeat;
}

/* Keyboard focus ring — clearly visible (≥3:1 against bg) */
input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
}

/* Invalid state */
input[type="checkbox"][aria-invalid="true"] {
  border-color: var(--color-error);
}

/* ── Checkbox label ───────────────────────────────────────── */
label[for="agree-terms"] {
  font-size: .9375rem;
  cursor: pointer;
  line-height: 1.5;
}

label[for="agree-terms"] a {
  color: var(--color-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}
label[for="agree-terms"] a:hover { color: var(--color-primary-h); }
label[for="agree-terms"] a:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ── Help & error text ────────────────────────────────────── */
.help-text {
  margin-top: .625rem;
  font-size: .8125rem;
  color: var(--color-muted);
  padding-left: 1.875rem; /* align under label text */
}

.error-text {
  margin-top: .5rem;
  font-size: .8125rem;
  color: var(--color-error);
  font-weight: 500;
  padding-left: 1.875rem;
}

/* ── Submit button ────────────────────────────────────────── */
button[type="submit"] {
  display: block;
  width: 100%;
  margin-top: 1.5rem;
  padding: .75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background .15s, transform .1s;
}
button[type="submit"]:hover  { background: var(--color-primary-h); }
button[type="submit"]:active { transform: scale(.98); }
button[type="submit"]:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 3px;
}

/* ── Success message ──────────────────────────────────────── */
.success-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .75rem;
  text-align: center;
  padding: 1.5rem 0 .5rem;
  color: var(--color-success);
}

.success-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  background: var(--color-success-bg);
  border-radius: 50%;
}

.success-icon svg { display: block; }

.success-message p {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
}

.success-message .success-sub {
  font-size: .875rem;
  color: var(--color-muted);
  font-weight: 400;
}

/* ── Forced colours (high-contrast mode) ─────────────────── */
@media (forced-colors: active) {
  input[type="checkbox"] {
    forced-color-adjust: auto;
  }
  button[type="submit"] {
    forced-color-adjust: auto;
  }
}

/* ── Reduced motion ───────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Narrow viewport reflow (≥320 px) ────────────────────── */
@media (max-width: 360px) {
  .card { padding: 1.25rem; }
}
