                           targets: v.nodes.map(n => n.target),
                           failureSummary: v.nodes.map(n => n.failureSummary) }))
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})().catch(e => { console.error(e.message); process.exit(2); });
